package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for UTF8JsonGenerator.writeRaw(String text, int offset, int len)
 */
public class UTF8JsonGenerator_writeRaw_TriageGen2Test {

    private ByteArrayOutputStream outputStream;
    private UTF8JsonGenerator generator;
    private IOContext ioContext;

    @Before
    public void setUp() {
        outputStream = new ByteArrayOutputStream();
        ioContext = new IOContext();
        // Using a small buffer size via the constructor to trigger the segmented approach (while loop)
        // The internal _charBuffer size is typically managed by BufferRecycler or a default value.
        // To force the 'while' loop to run multiple times, we rely on the fact that the internal
        // char buffer is finite.
        generator = new UTF8JsonGenerator(ioContext, 0, null, outputStream);
    }

    @After
    public void tearDown() throws IOException {
        generator.close();
    }

    @Test
    public void testWriteRaw_SimpleString() throws IOException {
        String text = "hello";
        generator.writeRaw(text, 0, text.length());
        generator.flush();

        assertEquals("hello", outputStream.toString(StandardCharsets.UTF_8));
    }

    @Test
    public void testWriteRaw_WithOffsetAndLength() throws IOException {
        String text = "abcdefg";
        // Write "cde" (offset 2, length 3)
        generator.writeRaw(text, 2, 3);
        generator.flush();

        assertEquals("cde", outputStream.toString(StandardCharsets.UTF_8));
    }

    @Test
    public void testWriteRaw_LargeString_TriggersSegmentation() throws IOException {
        // We create a string much larger than the internal _charBuffer to ensure the 'while' loop 
        // executes more than once (testing the len2 = Math.min(buf.length, len) logic).
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            sb.append("abc");
        }
        String largeText = sb.toString();
        int len = largeText.length();

        generator.writeRaw(largeText, 0, len);
        generator.flush();

        assertEquals(largeText, outputStream.toString(StandardCharsets.UTF_8));
    }

    @Test
    public void testWriteRaw_EmptyString() throws IOException {
        String text = "";
        generator.writeRaw(text, 0, 0);
        generator.flush();

        assertEquals("", outputStream.toString(StandardCharsets.UTF_8));
    }

    @Test
    public void testWriteRaw_UnicodeCharacters() throws IOException {
        // Testing multi-byte UTF-8 characters to ensure the byte conversion inside writeRaw(buf, 0, len2) works
        String text = "🚀 Java Test 漢字"; 
        generator.writeRaw(text, 0, text.length());
        generator.flush();

        assertEquals(text, outputStream.toString(StandardCharsets.UTF_8));
    }

    @Test
    public void testWriteRaw_SurrogatePairs() throws IOException {
        // Testing surrogate pairs (e.g., Emoji) which are 2 chars in Java String but 1 code point
        // This ensures the segmentation logic doesn't break the character encoding.
        String text = "\uD83D\uDE00"; // 😀
        generator.writeRaw(text, 0, text.length());
        generator.flush();

        assertEquals(text, outputStream.toString(StandardCharsets.UTF_8));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testWriteRaw_InvalidOffset() throws IOException {
        String text = "test";
        // Offset out of bounds
        generator.writeRaw(text, 10, 2);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testWriteRaw_InvalidLength() throws IOException {
        String text = "test";
        // Length extends beyond string bounds
        generator.writeRaw(text, 0, 10);
    }

    @Test
    public void testWriteRaw_SegmentedSurrogateBoundary() throws IOException {
        // This tests the scenario where a surrogate pair might be split across segments.
        // Since we cannot easily control the exact size of the private _charBuffer without reflection,
        // we use a very large string to force the 'while' loop to cycle.
        // The logic in the provided code snippet includes a comment about dropping split surrogates,
        // though the actual implementation provided in the prompt doesn't show the 'drop' logic,
        // we test that the loop handles large inputs correctly.

        StringBuilder sb = new StringBuilder();
        // Add many surrogate pairs
        for (int i = 0; i < 500; i++) {
            sb.append("\uD83D\uDE00"); 
        }
        String text = sb.toString();

        generator.writeRaw(text, 0, text.length());
        generator.flush();

        assertEquals(text, outputStream.toString(StandardCharsets.UTF_8));
    }
}
